57:         // Starts a background fetch unless one already succeeded or is in
58:         // flight. Fire-and-forget: called at IAP core init to warm the cache
59:         // before the first purchase, and again on each cache miss (failed
60:         // fetches retry on the next call).
61:         public void EnsureFetched()
62:         {
63:             if (s_Cached == null && !s_FetchInProgress)
64:             {
65:                 _ = FetchAndCacheAsync();
66:             }
67:         }
68: 
69:         async Task FetchAndCacheAsync()
70:         {
71:             // A reset during this fetch (a new Play session) bumps s_Generation: the fetch then neither
72:             // writes its result nor clears the in-progress flag, which belongs to the newer fetch.
73:             var generation = s_Generation;
74:             s_FetchInProgress = true;
75:             try
76:             {
77:                 var result = await FetchEnabledAttributesAsync();
78:                 if (result != null && generation == s_Generation)
79:                 {
80:                     s_Cached = result;
81:                 }
82:             }
83:             finally
84:             {
85:                 if (generation == s_Generation)
86:                 {
87:                     s_FetchInProgress = false;
88:                 }
89:             }
90:         }
