135:         internal static HashSet<string>? ParseEnabledAttributes(string json)
136:         {
137:             if (!(MiniJson.JsonDecode(json) is Dictionary<string, object> root))
138:             {
139:                 return null;
140:             }
141: 
142:             var enabled = new HashSet<string>();
143:             if (root.TryGetValue("attributeOverride", out var overrides)
144:                 && overrides is Dictionary<string, object> map)
145:             {
146:                 foreach (var entry in map)
147:                 {
148:                     if (entry.Value is bool collect && collect)
149:                     {
150:                         enabled.Add(entry.Key);
151:                     }
152:                 }
153:             }
154:             return enabled;
155:         }
