157:         static Task<string?> PostAsync(string url, string body)
158:         {
159:             var tcs = new TaskCompletionSource<string?>();
160:             var request = new UnityWebRequest(url, UnityWebRequest.kHttpVerbPOST)
161:             {
162:                 uploadHandler = new UploadHandlerRaw(System.Text.Encoding.UTF8.GetBytes(body)),
163:                 downloadHandler = new DownloadHandlerBuffer(),
164:                 timeout = 10
165:             };
166:             request.SetRequestHeader("Content-Type", "application/json");
167: 
168:             var op = request.SendWebRequest();
169:             op.completed += _ =>
170:             {
171:                 tcs.TrySetResult(request.result == UnityWebRequest.Result.Success
172:                     ? request.downloadHandler.text
173:                     : null);
174:                 request.Dispose();
175:             };
176:             return tcs.Task;
177:         }
