208: #if UNITY_INSIGHTS_REQUIREMENTS_API && ENABLE_CLOUD_SERVICES_ENGINE_DIAGNOSTICS
209:         static void ForwardModule(byte[] body)
210:         {
211:             // EngineDiagnostics.LogEvent takes a ReadOnlySpan<char>, so the
212:             // proto3 binary body is base64-encoded to fit a text channel
213:             // losslessly. The receiving side base64-decodes back to the same
214:             // bytes that ForwardGateway POSTs.
215:             EngineDiagnostics.LogEvent((int)InsightsEventType.IapSdk, Convert.ToBase64String(body));
216:         }
217: #endif
