93:         void UploadCompleted(long responseCode)
94:         {
95:             bool success = responseCode >= 200 && responseCode <= 299;
96:             bool badRequest = responseCode >= 400 && responseCode <= 499;
97:             bool intermittentError = responseCode >= 500 && responseCode <= 599 || m_FlushRequest.IsNetworkError;
98: 
99:             if (FlushFinished != null)
100:             {
101:                 FlushFinished((int)responseCode, success, badRequest, intermittentError, m_FlushRequest.IsNetworkError, m_LastFlushPayload);
102:             }
103: 
104:             if (success || badRequest)
105:             {
106: #if UNITY_ANALYTICS_EVENT_LOGS
107:                 if (ConsecutiveFailedUploadCount > 0)
108:                 {
109:                     Debug.Log("An upload request finally got through, consecutive failure count has been reset.");
110:                 }
111: #endif
112: 
113:                 ConsecutiveFailedUploadCount = 0;
114: 
115:                 // If we get a 2xx response code, the request is good and has gone through successfully,
116:                 // so we can safely discard the buffer knowing the data has reached its destination.
117:                 // If we get a 4xx response code, the request is bad and we should discard the buffer.
118:                 // Reasons include:
119:                 //  - JSON is malformed; we have a bad event somewhere and all we can do is bin the lot
120:                 //  - Project has been usage-gated and turned off; we will never get data through so might as well drop it all
121: 
122:                 m_DataBuffer.ClearBuffer(m_FlushBufferIndex);
123:                 m_DataBuffer.ClearDiskCache();
124: 
125: #if UNITY_ANALYTICS_EVENT_LOGS
126:                 if (success)
127:                 {
128:                     Debug.Log("Events uploaded successfully!");
129:                 }
130:                 else
131:                 {
132:                     Debug.Log($"Events upload failed ({responseCode}). Please visit the UGS Analytics dashboard to check for any relevant alerts. The event buffer has been cleared.");
133:                 }
134: #endif
135:             }
136:             else if (intermittentError)
137:             {
138:                 ConsecutiveFailedUploadCount++;
139: 
140:                 // Flush to disk in case we end up exiting before connectivity is re-established.
141:                 m_DataBuffer.FlushToDisk();
142: 
143: #if UNITY_ANALYTICS_EVENT_LOGS
144:                 if (m_FlushRequest.IsNetworkError)
145:                 {
146:                     Debug.Log("Events failed to upload (network error) -- upload will be reattempted later.");
147:                 }
148:                 else
149:                 {
150:                     Debug.LogFormat("Events failed to upload (code {0}) -- upload will be reattempted later.", responseCode);
151:                 }
152: #endif
153:             }
154: 
155:             // Clear the request now that we are done.
156:             FlushInProgress = false;
157:             m_FlushBufferIndex = 0;
158:             m_FlushRequest.Dispose();

51:         void DataFrameworkConsentChanged(ConsentState consentState)
52:         {
53:             if (UsingOriginalFlow)
54:             {
55:                 throw new InvalidOperationException(
56:                     "The Analytics SDK has already been activated using the StartDataCollection method. " +
57:                     "In order to use the Developer Data framework, you must remove references " +
58:                     "to Start/StopDataCollection and only use the EndUserConsent.SetConsentState(...) method.");
59:             }
60:             else
61:             {
62:                 UsingDataFrameworkFlow = true;
63:                 switch (consentState.AnalyticsIntent)
64:                 {
65:                     case ConsentStatus.Granted:
66:                         DataFrameworkConsentGranted = true;
67:                         ConsentGranted?.Invoke();
68:                         break;
69:                     case ConsentStatus.Denied:
70:                         DataFrameworkConsentGranted = false;
71:                         ConsentRevoked?.Invoke();
72:                         break;
73:                     case ConsentStatus.Unspecified:
74:                     default:
75:                         // This could happen at runtime if the developer clears consent state,
76:                         // rather than granting or denying. If consent was previously denied, then
77:                         // we are already off and there is nothing to do. If consent was previously
78:                         // granted, then revoke it.
79:                         if (DataFrameworkConsentGranted)
80:                         {
81:                             DataFrameworkConsentGranted = false;
82:                             ConsentRevoked?.Invoke();
83:                         }
84:                         break;
85:                 }
86:             }
87:         }
