2353:         // process remote triggers independently from other response processing
2354:         if (responseData.jsonResponse == null) {
2355:             return;
2356:         }
2357: 
2358:         JSONArray remoteTriggers = responseData.jsonResponse.optJSONArray("remote_triggers");
2359: 
2360:         if (remoteTriggers == null) {
2361:             return;
2362:         }
2363: 
2364:         if (remoteTriggers.length() == 0) {
2365:             return;
2366:         }
2367: 
2368:         if (adjustConfig.onRemoteTriggerListener == null) {
2369:             return;
2370:         }
2371: 
2372:         // process each remote trigger in order
2373:         for (int i = 0; i < remoteTriggers.length(); i++) {
2374:             JSONObject remoteTrigger = remoteTriggers.optJSONObject(i);
2375:             if (remoteTrigger == null) {
2376:                 logger.warn("Invalid remote trigger item, skipping");
2377:                 continue;
2378:             }
2379: 
2380:             String label = remoteTrigger.optString("label");
2381:             if (label.isEmpty()) {
2382:                 logger.warn("Remote trigger missing or invalid label, skipping");
2383:                 continue;
2384:             }
2385: 
2386:             JSONObject payload = remoteTrigger.optJSONObject("payload");
2387:             if (payload == null) {
2388:                 logger.warn("Remote trigger missing or invalid payload, skipping");
2389:                 continue;
2390:             }
2391: 
2392:             final AdjustRemoteTrigger adjustRemoteTrigger = new AdjustRemoteTrigger(label, payload);
2393:             Handler handler = new Handler(adjustConfig.context.getMainLooper());
2394:             Runnable runnable = new Runnable() {
2395:                 @Override
2396:                 public void run() {
2397:                     if (adjustConfig.onRemoteTriggerListener != null) {
2398:                         adjustConfig.onRemoteTriggerListener.onRemoteTrigger(adjustRemoteTrigger);
2399:                     }
2400:                 }
2401:             };
2402:             handler.post(runnable);
2403:         }
